import numpy as np
from scipy.integrate import quad

def V(mu: float, c0: float, c1: float, c2: float) -> float:
    """The physical owner model (generalized variance function)."""
    return c0 + c1 * mu + c2 * (mu ** 2)

def D_V(x: float, mu: float, c0: float, c1: float, c2: float) -> float:
    """Quasi-deviance function generated by the variance model V."""
    def integrand(u):
        return (x - u) / V(u, c0, c1, c2)
    res, _ = quad(integrand, mu, x)
    return 2.0 * res

def admission_responsibility(sigma_func, c_t: float, D_V_val: float, eps_t: float, is_valid: bool = True) -> float:
    """Admission responsibility evaluation. strictly 0 if invalid."""
    if not is_valid:
        return 0.0
    return sigma_func((c_t - D_V_val) / eps_t)

def causal_ema_step(mu_t: float, x_t: float, r_t: float, rho_N_t: float) -> float:
    """Causal Adaptive EMA Step."""
    if rho_N_t + r_t == 0.0:
        return mu_t
    return mu_t + (r_t / (rho_N_t + r_t)) * (x_t - mu_t)

def full_temporal_update(sigma_func, c0: float, c1: float, c2: float, rho_N_t: float, c_t: float, eps_t: float, x_t: float, mu_t: float, is_valid: bool = True) -> float:
    """The full temporal update step combining admission and causal EMA."""
    D_val = D_V(x_t, mu_t, c0, c1, c2)
    r_t = admission_responsibility(sigma_func, c_t, D_val, eps_t, is_valid)
    return causal_ema_step(mu_t, x_t, r_t, rho_N_t)

class StableCentralMoments:
    """Welford's online algorithm for stable central moments (mean and variance)."""
    def __init__(self):
        self.n = 0
        self.mean = 0.0
        self.M2 = 0.0

    def update(self, x: float, is_valid: bool = True):
        if not is_valid:
            return
        self.n += 1
        delta = x - self.mean
        self.mean += delta / self.n
        delta2 = x - self.mean
        self.M2 += delta * delta2

    def variance(self) -> float:
        if self.n < 2:
            return 0.0
        return self.M2 / (self.n - 1)

    def get_mean(self) -> float:
        return self.mean

def test_cmos_oracle():
    # Simple sigmoid for testing
    def sigmoid(x):
        return 1.0 / (1.0 + np.exp(-x))
    
    c0, c1, c2 = 1.0, 0.1, 0.01
    mu_t = 10.0
    x_t = 12.0
    rho_N_t = 5.0
    c_t = 5.0
    eps_t = 1.0
    
    mu_next = full_temporal_update(sigmoid, c0, c1, c2, rho_N_t, c_t, eps_t, x_t, mu_t, is_valid=True)
    print(f"mu_next (valid): {mu_next}")
    
    mu_next_invalid = full_temporal_update(sigmoid, c0, c1, c2, rho_N_t, c_t, eps_t, x_t, mu_t, is_valid=False)
    print(f"mu_next (invalid): {mu_next_invalid}")
    assert mu_next_invalid == mu_t, "Background state should not drift for invalid measurements"

if __name__ == "__main__":
    test_cmos_oracle()
